export function bridgesEvidence(record){
 const r=record.result;
 switch(record.action){
  case'hubbard_lab':return `fixed (N↑,N↓)=(${r.sector.nUp},${r.sector.nDown})；E_0=${num(r.ground.energy)} eV；⟨S²⟩=${num(r.ground.totalSpinSquared)}；Δ_{ST}=${num(r.gaps.dimerSingletTriplet?.gap)} eV; this spectrum has a fixed number of particles, not an add/remove spectrum`;
  case'polaron_lab':return `g=${num(r.parameters.coupling)} eV; electron density =(${r.ground.density.map(num).join(', ')}); phonon number =${num(r.ground.phononOccupation.reduce((a,b)=>a+b,0))}; Electronic purity =${num(r.ground.electronicPurity)}; Adjacent truncation δE=${num(r.convergence.energyChangeEV)} eV; phonon truncated${r.convergence.converged?"passes the current threshold":"has not yet converged"}; X is dimensionless`;
  case'density_matrix_lab':{const s=r.stateSnapshots,last=s.at(-1);return `Spin number =${r.scope.spins}; Initial overall purity =${num(s[0].purity)}; final purity =${num(last.purity)}; Final state A entropy =${num(last.entropyA)} bit；${r.scope.spins===2?`maximum negativity of trajectory =${num(Math.max(...s.map(x=>x.negativity)))}; final state negative =${num(last.negativity)}；`:''}γφ=${num(r.rates.gammaPhi)} ns⁻¹; local entropy and mixed state entanglement must be distinguished`;}
  case'teaching_labs':if(r.experiment!=='su2_coupling')return null;return `Spin direct product dimension =${r.dimension}；${r.selected.expansion.map(e=>`S=${num(e.J)}: Probability =${num(e.probability)}, exchange energy =${num(e.energy)}`).join('；')}; κ uses the specified energy unit, and kinetics needs to be converted to κ=ℏJ`;
  case'symmetry_workshop':return `allowed dimensions =${r.workshop.nullspace[0]?.length||0}; generator number =${r.workshop.generators.length};Polynomial residual =${num(r.checks.polynomialResidual)}; Γ split =${num(r.summary.find(x=>x.label==="Γ point splitting after projection")?.value)} eV; local second-order model of homoparity spin doublets`;
  case'band_connectivity':return `${r.model}; General paths and endpoints must be distinguished; Γ/X split =${r.crossings.map(x=>`${x.label}:${num(x.gap)}`).join(', ')}； time reversal =${r.validation.timeReversalPresent?"Reserved":"broken"}; Mirror =${r.validation.mirrorSymmetryPresent?"Reserved":"broken"}; number of path points =${r.summary.sampleCount}; Energy is model unit`;
  case'manybody_spectra_lab':return r.summary.map(x=>`${x.label}=${typeof x.value==='number'?num(x.value):x.value}${x.unit?' '+x.unit:''}`).join('；')+"; explain spectral weights using the actual transition matrix elements. An arbitrary energy-level difference cannot be identified with an observable spectral peak";
  default:return null;
 }
}
